window.AUTH=window.AUTH||{};window.AUTH["20-1114"]={"d":"20-1114","id":"2021/20-1114","n":"American Hospital Association v. Becerra","briefs":[{"k":"petitioner","label":"Brief of petitioners American Hospital Association, et al.","date":"2021-09-03","url":"https://www.supremecourt.gov/DocketPDF/20/20-1114/191385/20210903135030675_20-1114%20-%20AHA%20v%20Becerra%20-%20Brief%20for%20the%20Petitioners.pdf","side":"pet","n":102},{"k":"respondent","label":"Brief of respondents Xavier Becerra, Sec. of H&HS, et al.","date":"2021-10-20","url":"https://www.supremecourt.gov/DocketPDF/20/20-1114/197027/20211020212647625_20-1114bsUnitedStates.pdf","side":"res","n":93},{"k":"reply","label":"Reply of petitioners American Hospital Association, et al.","date":"2021-11-19","url":"https://www.supremecourt.gov/DocketPDF/20/20-1114/200670/20211119130820657_20-1114%20AHA%20Reply.pdf","side":"pet","n":39}],"opinion":"https://www.supremecourt.gov/opinions/21pdf/596us2r46_bqm1.pdf","tr":true,"items":[{"t":"case","label":"FEDERAL CASES Ali v. Fed. Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"sum":"The Court agreed with the 11th Circuit and, in a 5-4 majority opinion written by Justice Clarence Thomas, held that the use of the word \"any\" should be given its normal interpretation, encompassing all federal officers whether or not they were involved in enforcing customs or excise laws.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"Amgen, Inc. v. Smith","cite":"357 F.3d 103","y":2004,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/357/103/","op":1,"by":{"0":"30, 36","1":"passim","2":"9, 18"}},{"t":"case","label":"Astra USA, Inc. v. Santa Clara Cnty.","cite":"563 U.S. 110","y":2011,"id":"2010/09-1273","sc":1,"sum":"The Court held that health care providers cannot sue drug makers for overcharging public hospitals for prescription drugs.","sumSrc":"Oyez","by":{"0":"39, 40","1":"9, 44"}},{"t":"case","label":"Babb v. Wilkie","cite":"140 S. Ct. 1168","y":2020,"id":"2019/18-882","sc":1,"op":1,"sum":"The Court held that the federal-sector provision of the Age Discrimination in Employment Act of 1967 demands that personnel actions be untainted by any consideration of age, but but-for causation is important in determining the appropriate remedy that may be obtained.","sumSrc":"Oyez","by":{"0":"27","2":"6"}},{"t":"case","label":"Baldwin v. United States","cite":"140 S. Ct. 690","y":2020,"url":"https://www.courtlistener.com/c/S.%20Ct./140/690/","sc":1,"by":{"0":"50"}},{"t":"case","label":"Bd. of Governors of Fed. Rsrv. Sys. v. MCorp Fin., Inc.","cite":"502 U.S. 32","y":1991,"id":"1991/90-913","sc":1,"sum":"The District Court lacked jurisdiction to enjoin either regulatory proceeding.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19","1":"31"}},{"t":"case","label":"Bolivarian Republic of Venezuela v. Helmerich & Payne Int’l Drilling Co.","cite":"137 S. Ct. 1312","y":2017,"id":"2016/15-423","sc":1,"sum":"The Court determined that the “frivolous or insubstantial” standard is not consistent with the text and purpose of the Foreign Sovereign Immunities Act (FSIA)","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Bowen v. Mich. Acad. of Fam. Physicians","cite":"476 U.S. 667","y":1986,"id":"1985/85-225","sc":1,"sum":"In neither 42 U. S. C. § 1395ff (1982 ed. and Supp. II) nor § 1395ii (1982 ed., Supp. II), has Congress barred judicial review of regulations promulgated under Part B of the Medicare program.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16, 29"}},{"t":"case","label":"Chevron, U.S.A., Inc. v. Natural Resources Defense Council, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"ar":26,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"0":"passim","1":"19, 47, 48"}},{"t":"case","label":"City of Arlington v. FCC","cite":"569 U.S. 290","y":2013,"id":"2012/11-1545","sc":1,"sum":"The Court found that the courts must apply the Chevron doctrine and defer to an agency's interpretation of its jurisdiction when that jurisdiction is called into question.","sumSrc":"Oyez","by":{"0":"48"}},{"t":"case","label":"Cyan, Inc. v. Beaver Cnty. Emps. Ret. Fund","cite":"138 S. Ct. 1061","y":2018,"id":"2017/15-1439","sc":1,"sum":"The Court held that that the Securities Litigation Uniform Standards Act of 1998 does not strip state courts of jurisdiction to hear claims under the Securities Act of 1933, nor does it permit defendants to remove class actions alleging only 1933 Act claims from state to federal court.","sumSrc":"Oyez","by":{"0":"42","1":"39"}},{"t":"case","label":"E.I. du Pont de Nemours & Co. v. Train","cite":"430 U.S. 112","y":1977,"id":"1976/75-978","sc":1,"sum":"The Court held that the Environmental Protection Agency could place categorical pollution limits on existing manufacturing plants while also placing absolute pollution limits on newly constructed manufacturing plants.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"138 S. Ct. 1612","y":2018,"id":"2017/16-285","sc":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"0":"31, 47"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"sum":"The Court held that \"Congress has not given the FDA the authority to regulate tobacco products as customarily marketed.\" The ruling was based on the FDCA as a whole and in conjunction with Congress' subsequent tobacco-specific legislation. \"By no means do we question the seriousness of the problem that the FDA has sought to address,\" Justice O'Connor wrote for the majority.","sumSrc":"Oyez","by":{"0":"41, 49"}},{"t":"case","label":"Freeman v. Quicken Loans, Inc.","cite":"566 U.S. 624","y":2012,"id":"2011/10-1042","sc":1,"sum":"The Court held that Section 8(b) of the Real Estate Settlement Procedures Act prohibits a real estate service provider from charging an unearned fee if the fee is divided between two or more parties.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Gonzales v. Oregon","cite":"546 U.S. 243","y":2006,"id":"2005/04-623","sc":1,"sum":"The Court decided that the Controlled Substance Act did not ban the use of controlled substances in physician-assisted suicide, nor does the Attorney General have the power to determine what is a violation of the Act.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"H. Lee Moffitt Cancer Ctr. v. Azar","cite":"324 F. Supp. 3d 1","y":2018,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/324/1/","by":{"0":"29","1":"30","2":"8, 9"}},{"t":"case","label":"Kisor v. Wilkie","cite":"139 S. Ct. 2400","y":2019,"id":"2018/18-15","sc":1,"ar":2,"sum":"Auer v. Robbins, 519 U. S. 452, and Bowles v. Seminole Rock & Sand Co., 325 U. S. 410—under which deference is given to an agency’s reasonable reading of its own genuinely ambiguous regulations—are not overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"16, 47","1":"47"}},{"t":"case","label":"Lindahl v. OPM","cite":"470 U.S. 768","y":1985,"id":"1984/83-5954","sc":1,"sum":"The Office of Personnel Management (OPM) \"determine[s] questions of disability and dependency\" in administering the Federal Government's disability retirement program. 5 U. S. C. § 8347(c). Its \"decisions... concerning these matters are final and conclusive and are not subject to review,\" ibid., except to the extent that administrative review by the Merit Systems Protection Board (MSPB) is provided by §8347(d)(1). …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18"}},{"t":"case","label":"Mach Mining, LLC v. EEOC","cite":"575 U.S. 480","y":2015,"id":"2014/13-1019","sc":1,"op":2,"sum":"The Court held that judicial review of the Equal Employment Opportunity Commission’s efforts at conciliation is appropriate, but such review must be limited to the narrow requirements that Title VII imposes.","sumSrc":"Oyez","by":{"0":"16, 17, 18","1":"26"}},{"t":"case","label":"MCI Telecomms. Corp. v. AT&T","cite":"512 U.S. 218","y":1994,"id":"1993/93-356","sc":1,"sum":"The Commission's permissive detariffing policy is not a valid exercise of its §203(b)(2) authority to \"modify any requirement.\" Because virtually every dictionary in use now and at the time the statute was enacted defines \"to modify\" as meaning to change moderately or in minor fashion, the word \"modify\" must be seen to have a connotation of increment or limitation. That § 203(b)(2) does not contemplate basic or …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"47","2":"12, 23"}},{"t":"case","label":"Michigan v. EPA","cite":"576 U.S. 743","y":2015,"id":"2014/14-46","sc":1,"ar":1,"sum":"The Court determined that the Environmental Protection Agency (EPA) unreasonably interpreted the Clean Air Act by not considering costs to power plants in deciding that regulation was “appropriate and necessary.”","sumSrc":"Oyez","by":{"0":"50","1":"41, 48"}},{"t":"case","label":"Negusie v. Holder","cite":"555 U.S. 511","y":2009,"id":"2008/07-499","sc":1,"sum":"The Court held that the Board of Immigration Appeals (BIA) incorrectly interpreted provisions of the Immigration and Nationality Act (INA) from a mistaken legal premise.","sumSrc":"Oyez","by":{"0":"48"}},{"t":"case","label":"PDR Network, LLC v. Carlton & Harris Chiropractic, Inc.","cite":"139 S. Ct. 2051","y":2019,"id":"2018/17-1705","sc":1,"sum":"The Court held that Fourth Circuit did not properly consider preliminary issues that determine whether a district court must accept the Federal Communication Commission's legal interpretation of the Telephone Consumer Protection Act.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Reno v. Cath. Soc. Servs., Inc.","cite":"509 U.S. 43","y":1993,"id":"1992/91-1826","sc":1,"sum":"The record is insufficient to allow this Court to decide all issues necessary to determine whether the District Courts had jurisdiction.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Salinas v. U.S. R.R. Ret. Bd.","cite":"141 S. Ct. 691","y":2021,"id":"2020/19-199","sc":1,"sum":"The U. S. Railroad Retirement Board’s denial of a request to reopen a prior benefits determination under the Railroad Retirement Act of 1974 and the Railroad Unemployment Insurance Act is subject to judicial review.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"27, 33"}},{"t":"case","label":"SAS Inst., Inc. v. Iancu","cite":"138 S. Ct. 1348","y":2018,"id":"2017/16-969","sc":1,"sum":"The Court decided that when the United States Patent and Trademark Office institutes an inter partes review to reconsider an already-issued patent claim, under 35 U.S.C. §§ 311-319, it must decide the patentability of all of the claims the petitioner has challenged.","sumSrc":"Oyez","by":{"0":"45, 47"}},{"t":"case","label":"Shands Jacksonville Med. Ctr., Inc. v. Azar","cite":"366 F. Supp. 3d 32","y":2018,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/366/32/","by":{"0":"29","1":"30"}},{"t":"case","label":"United States v. Nourse","cite":"34 U.S. 8","y":1835,"id":"scdb/1835-008","sc":1,"sum":"The treasury department of the United States, on the 14th of July 1829, issued a warrant of distress directed to the marshal of the District of Columbia, Commanding him to levy and collect, by distress and sale of his goods and chattels, a sum of money alleged to be due to the United States, on a treasury transcript, by Joseph Nourse, late register of the treasury. This warrant was issued in pursuance of the 3d and …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"16-17"}},{"t":"case","label":"Universal Health Servs. of McAllen, Inc. v. Sullivan","cite":"770 F. Supp. 704","y":1991,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp./770/704/","by":{"0":"29-30","2":"9"}},{"t":"case","label":"Util. Air Regul. Grp. v. EPA","cite":"573 U.S. 302","y":2014,"id":"2013/12-1146","sc":1,"sum":"The Court held that, under the Clean Air Act, the EPA is not required to include greenhouse gas emissions every time it mentions air pollution.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"Whitman v. Am. Trucking Ass’ns","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"op":1,"sum":"The Court held that the CAA properly delegated legislative power to the EPA, but that the EPA could not consider implementation costs in setting primary and secondary NAAQS.","sumSrc":"Oyez","by":{"0":"passim","2":"15"}},{"t":"case","label":"Whitman v. Dep’t of Transp.","cite":"547 U.S. 512","y":2006,"id":"2005/04-1131","sc":1,"sum":"The Justices declined to rule on whether the District Court should have taken Whitman's case, because lower courts had not determined exactly \"where Whitman's claims fit within the statutory scheme.\" The Court sent the case back to the Court of Appeals with instructions to rule on this question. (Justice Alito took no part in the decision of this case.).","sumSrc":"Oyez","by":{"0":"29"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","subs":["(2)"],"by":{"0":"14"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"42 U.S.C. § 256b","url":"https://www.law.cornell.edu/uscode/text/42/256b","subs":["(a)","(a)(4)","(a)(1)","(a)(3)","(a)(8)"],"stext":{"head":"§256b. Limitation on prices of drugs purchased by covered entities","paras":[[0,"(a) Requirements for agreement with Secretary"],[0,"(1) In general"],[1,"The Secretary shall enter into an agreement with each manufacturer of covered outpatient drugs under which the amount required to be paid (taking into account any rebate or discount, as provided by the Secretary) to the manufacturer for covered outpatient drugs (other than drugs described in paragraph (3)) purchased by a covered entity on or after the first day of the first month that begins after November 4, 1992, does not exceed an amount equal to the average manufacturer price for the drug under title XIX of the Social Security Act [42 U.S.C. 1396 et seq.] in the preceding calendar quarter, reduced by the rebate percentage described in paragraph (2). Each such agreement shall require that the manufacturer furnish the Secretary with reports, on a quarterly basis, of the price for each covered outpatient drug subject to the agreement that, according to the manufacturer, represents the maximum price that covered entities may permissibly be required to pay for the drug (referred to in this section as the \"ceiling price\"), and shall require that the manufacturer offer each covered entity covered outpatient drugs for purchase at or below the applicable ceiling price if such drug is made available to any other purchaser at any price."],[0,"(2) \"Rebate percentage\" defined"],[0,"(A) In general"],[2,"For a covered outpatient drug purchased in a calendar quarter, the \"rebate percentage\" is the amount (expressed as a percentage) equal to—"],[3,"(i) the average total rebate required under section 1927(c) of the Social Security Act [42 U.S.C. 1396r–8(c)] with respect to the drug (for a unit of the dosage form and strength involved) during the preceding calendar quarter; divided by"],[3,"(ii) the average manufacturer price for such a unit of the drug during such quarter."],[0,"(B) Over the counter drugs"],[0,"(i) In general"],[3,"For purposes of subparagraph (A), in the case of over the counter drugs, the \"rebate percentage\" shall be determined as if the rebate required under section 1927(c) of the Social Security Act [42 U.S.C. 1396r–8(c)] is based on the applicable percentage provided under section 1927(c)(3) of such Act."],[0,"(ii) \"Over the counter drug\" defined"],[3,"The term \"over the counter drug\" means a drug that may be sold without a prescription and which is prescribed by a physician (or other persons authorized to prescribe such drug under State law)."],[0,"(3) Drugs provided under State medicaid plans"],[1,"Drugs described in this paragraph are drugs purchased by the entity for which payment is made by the State under the State plan for medical assistance under title XIX of the Social Security Act [42 U.S.C. 1396 et seq.]."],[0,"(4) \"Covered entity\" defined"],[1,"In this section, the term \"covered entity\" means an entity that meets the requirements described in paragraph (5) and is one of the following:"],[2,"(A) A Federally-qualified health center (as defined in section 1905(l)(2)(B) of the Social Security Act [42 U.S.C. 1396d(l)(2)(B)])."],[2,"(B) An entity receiving a grant under section 256a 1 of this title."],[2,"(C) A family planning project receiving a grant or contract under section 300 of this title."],[2,"(D) An entity receiving a grant under subpart II 1 of part C of subchapter XXIV (relating to categorical grants for outpatient early intervention services for HIV disease)."],[2,"(E) A State-operated AIDS drug purchasing assistance program receiving financial assistance under subchapter XXIV."],[2,"(F) A black lung clinic receiving funds under section 937(a) of title 30."],[2,"(G) A comprehensive hemophilia diagnostic treatment center receiving a grant under section 501(a)(2) of the Social Security Act [42 U.S.C. 701(a)(2)]."],[2,"(H) A Native Hawaiian Health Center receiving funds under the Native Hawaiian Health Care Act of 1988."],[2,"(I) An urban Indian organization receiving funds under title V of the Indian Health Care Improvement Act [25 U.S.C. 1651 et seq.]."],[2,"(J) Any entity receiving assistance under subchapter XXIV (other than a State or unit of local government or an entity described in subparagraph (D)), but only if the entity is certified by the Secretary pursuant to paragraph (7)."],[2,"(K) An entity receiving funds under section 247c of this title (relating to treatment of sexually transmitted diseases) or section 247b(j)(2) 1 of this title (relating to treatment of tuberculosis) through a State or unit of local government, but only if the entity is certified by the Secretary pursuant to paragraph (7)."],[2,"(L) A subsection (d) hospital (as defined in section 1886(d)(1)(B) of the Social Security Act [42 U.S.C. 1395ww(d)(1)(B)]) that—"],[3,"(i) is owned or operated by a unit of State or local government, is a public or private non-profit corporation which is formally granted governmental powers by a unit of State or local government, or is a private non-profit hospital which has a contract with a State or local government to provide health care services to low income individuals who are not entitled to benefits under title XVIII of the Social Security Act [42 U.S.C. 1395 et seq.] or eligible for assistance under the State plan under this subchapter;"],[3,"(ii) for the most recent cost reporting period that ended before the calendar quarter involved, had a disproportionate share adjustment percentage (as determined under section 1886(d)(5)(F) of the Social Security Act [42 U.S.C. 1395ww(d)(5)(F)]) greater than 11.75 percent or was described in section 1886(d)(5)(F)(i)(II) of such Act [42 U.S.C. 1395ww(d)(5)(F)(i)(II)]; and"],[3,"(iii) does not obtain covered outpatient drugs through a group purchasing organization or other group purchasing arrangement."],[2,"(M) A children's hospital excluded from the Medicare prospective payment system pursuant to section 1886(d)(1)(B)(iii) of the Social Security Act [42 U.S.C. 1395ww(d)(1)(B)(iii)], or a free-standing cancer hospital excluded from the Medicare prospective payment system pursuant to section 1886(d)(1)(B)(v) of the Social Security Act, that would meet the requirements of subparagraph (L), including the disproportionate share adjustment percentage requirement under clause (ii) of such subparagraph, if the hospital were a subsection (d) hospital as defined by section 1886(d)(1)(B) of the Social Security Act."],[2,"(N) An entity that is a critical access hospital (as determined under section 1820(c)(2) of the Social Security Act [42 U.S.C. 1395i–4(c)(2)]), and that meets the requirements of subparagraph (L)(i)."],[2,"(O) An entity that is a rural referral center, as defined by section 1886(d)(5)(C)(i) of the Social Security Act [42 U.S.C. 1395ww(d)(5)(C)(i)], or a sole community hospital, as defined by section 1886(d)(5)(C)(iii) of such Act, and that both meets the requirements of subparagraph (L)(i) and has a disproportionate share adjustment percentage equal to or greater than 8 percent."],[0,"(5) Requirements for covered entities"],[0,"(A) Prohibiting duplicate discounts or rebates"],[0,"(i) In general"],[3,"A covered entity shall not request payment under title XIX of the Social Security Act [42 U.S.C. 1396 et seq.] for medical assistance described in section 1905(a)(12) of such Act [42 U.S.C. 1396d(a)(12)] with respect to a drug that is subject to an agreement under this section if the drug is subject to the payment of a rebate to the State under section 1927 of such Act [42 U.S.C. 1396r–8]."],[0,"(ii) Establishment of mechanism"],[3,"The Secretary shall establish a mechanism to ensure that covered entities comply with clause (i). If the Secretary does not establish a mechanism within 12 months under the previous sentence, the requirements of section 1927(a)(5)(C) of the Social Security Act [42 U.S.C. 1396r–8(a)(5)(C)] shall apply."],[0,"(B) Prohibiting resale of drugs"],[2,"With respect to any covered outpatient drug that is subject to an agreement under this subsection, a covered entity shall not resell or otherwise transfer the drug to a person who is not a patient of the entity."],[0,"(C) Auditing"],[2,"A covered entity shall permit the Secretary and the manufacturer of a covered outpatient drug that is subject to an agreement under this subsection with the entity (acting in accordance with procedures established by the Secretary relating to the number, duration, and scope of audits) to audit at the Secretary's or the manufacturer's expense the records of the entity that directly pertain to the entity's compliance with the requirements described in subparagraphs 2 (A) or (B) with respect to drugs of the manufacturer."],[0,"(D) Additional sanction for noncompliance"],[2,"If the Secretary finds, after audit as described in subparagraph (C) and after notice and hearing, that a covered entity is in violation of a requirement described in subparagraphs 2 (A) or (B), the covered entity shall be liable to the manufacturer of the covered outpatient drug that is the subject of the violation in an amount equal to the reduction in the price of the drug (as described in subparagraph (A)) provided under the agreement between the entity and the manufacturer under this paragraph."],[0,"(6) Treatment of distinct units of hospitals"],[1,"In the case of a covered entity that is a distinct part of a hospital, the hospital shall not be considered a covered entity under this paragraph unless the hospital is otherwise a covered entity under this subsection."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/256b?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§256b. Limitation on prices of drugs purchased by covered entities","tname":"The Public Health and Welfare","by":{"0":"9, 40","1":"9, 9, 9, 9, 9"}},{"t":"usc","label":"42 U.S.C. § 1395l","url":"https://www.law.cornell.edu/uscode/text/42/1395l","subs":["(i)(2)(D)(vi)","(m)","(m)(4)","(t)","(t)(2)","(t)(2)(C)","(t)(2)(D)","(t)(2)(E)","(t)(2)(F)","(t)(5)","(t)(6)","(t)(7)","(t)(9)","(t)(9)(A)","(t)(9)(B)","(t)(12)","(t)(12)(A)","(t)(12)(C)","(t)(12)(E)","(t)(13)","(t)(13)(B)","(t)(14)","(t)(14)(A)","(t)(14)(A)(i)","(t)(14)(A)(iii)","(t)(14)(A)(iii)(I)","(t)(14)(A)(iii)(II)","(t)(14)(C)","(t)(14)(D)","(t)(14)(D)(i)","(t)(14)(D)(i)(I)","(t)(14)(D)(i)(II)","(t)(14)(D)(ii)","(t)(14)(D)(iii)","(t)(14)(D)(iv)","(t)(14)(D)(v)","(t)(14)(E)","(t)(14)(H)","(t)(18)(B)","(t)(21)","(t)(21)(E)","(u)","(u)(4)(E)","(x)(4)","(z)(4)","(t)(2)(A)","(t)(2)(B)","(t)(3)","(t)(3)(B)","(t)(3)(D)","(t)(4)","(t)(5)(B)","(t)(8)","(t)(14)(A)(ii)","(t)(14)(B)(i)","(t)(14)(B)(i)(II)","(t)(14)(E)(i)","(t)(16)(D)(i)(I)","(t)(3)(B)(iii)","(t)(3)(C)(i)(II)","(t)(7)(D)(I)(i)","(t)(8)(C)","(t)(12)(B)","(t)(12)(D)"],"stext":{"head":"§1395l. Payment of benefits","paras":[[0,"(a) Amounts"],[0,"Except as provided in section 1395mm of this title, and subject to the succeeding provisions of this section, there shall be paid from the Federal Supplementary Medical Insurance Trust Fund, in the case of each individual who is covered under the insurance program established by this part and incurs expenses for services with respect to which benefits are payable under this part, amounts equal to—"],[1,"(1) in the case of services described in section 1395k(a)(1) of this title—80 percent of the reasonable charges for the services; except that (A) an organization which provides medical and other health services (or arranges for their availability) on a prepayment basis (and either is sponsored by a union or employer, or does not provide, or arrange for the provision of, any inpatient hospital services) may elect to be paid 80 percent of the reasonable cost of services for which payment may be made under this part on behalf of individuals enrolled in such organization in lieu of 80 percent of the reasonable charges for such services if the organization undertakes to charge such individuals no more than 20 percent of such reasonable cost plus any amounts payable by them as a result of subsection (b), (B) with respect to items and services described in section 1395x(s)(10)(A) of this title, the amounts paid shall be 100 percent of the reasonable charges for such items and services, (C) with respect to expenses incurred for those physicians' services for which payment may be made under this part that are described in section 1395y(a)(4) of this title, the amounts paid shall be subject to such limitations as may be prescribed by regulations, (D) with respect to clinical diagnostic laboratory tests for which payment is made under this part (i)(I) on the basis of a fee schedule under subsection (h)(1) (for tests furnished before January 1, 2017) or section 1395m(d)(1) of this title, the amount paid shall be equal to 80 percent (or 100 percent, in the case of such tests for which payment is made on an assignment-related basis) of the lesser of the amount determined under such fee schedule, the limitation amount for that test determined under subsection (h)(4)(B), or the amount of the charges billed for the tests, or (II) under section 1395m–1 of this title (for tests furnished on or after January 1, 2017), the amount paid shall be equal to 80 percent (or 100 percent, in the case of such tests for which payment is made on an assignment-related basis) of the lesser of the amount determined under such section or the amount of the charges billed for the tests, or (ii) for tests furnished before January 1, 2017, on the basis of a negotiated rate established under subsection (h)(6), the amount paid shall be equal to 100 percent of such negotiated rate,,1 (E) with respect to services furnished to individuals who have been determined to have end stage renal disease, the amounts paid shall be determined subject to the provisions of section 1395rr of this title, (F) with respect to clinical social worker services under section 1395x(s)(2)(N) of this title, the amounts paid shall be 80 percent of the lesser of (i) the actual charge for the services or (ii) 75 percent of the amount determined for payment of a psychologist under clause (L), (G) with respect to facility services furnished in connection with a surgical procedure specified pursuant to subsection (i)(1)(A) and furnished to an individual in an ambulatory surgical center described in such subsection, for services furnished beginning with the implementation date of a revised payment system for such services in such facilities specified in subsection (i)(2)(D), the amounts paid, subject to subsection (i)(9), shall be 80 percent of the lesser of the actual charge for the services or the amount determined by the Secretary under such revised payment system, (H) with respect to services of a certified registered nurse anesthetist under section 1395x(s)(11) of this title, the amounts paid shall be 80 percent of the least of the actual charge, the prevailing charge that would be recognized (or, for services furnished on or after January 1, 1992, the fee schedule amount provided under section 1395w–4 of this title) if the services had been performed by an anesthesiologist, or the fee schedule for such services established by the Secretary in accordance with subsection (l), (I) with respect to covered items (described in section 1395m(a)(13) of this title), the amounts paid shall be the amounts described in section 1395m(a)(1) of this title, and 2 (J) with respect to expenses incurred for radiologist services (as defined in section 1395m(b)(6) of this title), subject to section 1395w–4 of this title, the amounts paid shall be 80 percent of the lesser of the actual charge for the services or the amount provided under the fee schedule established under section 1395m(b) of this title, (K) with respect to certified nurse-midwife services under section 1395x(s)(2)(L) of this title, the amounts paid shall be 80 percent of the lesser of the actual charge for the services or the amount determined by a fee schedule established by the Secretary for the purposes of this subparagraph (but in no event shall such fee schedule exceed 65 percent of the prevailing charge that would be allowed for the same service performed by a physician, or, for services furnished on or after January 1, 1992, 65 percent (or 100 percent for services furnished on or after January 1, 2011) of the fee schedule amount provided under section 1395w–4 of this title for the same service performed by a physician), (L) with respect to qualified psychologist services under section 1395x(s)(2)(M) of this title, the amounts paid shall be 80 percent of the lesser of the actual charge for the services or the amount determined by a fee schedule established by the Secretary for the purposes of this subparagraph, (M) with respect to prosthetic devices and orthotics and prosthetics (as defined in section 1395m(h)(4) of this title), the amounts paid shall be the amounts described in section 1395m(h)(1) of this title, (N) with respect to expenses incurred for physicians' services (as defined in section 1395w–4(j)(3) of this title) other than personalized prevention plan services (as defined in section 1395x(hhh)(1) of this title), the amounts paid shall be 80 percent of the payment basis determined under section 1395w–4(a)(1) of this title, (O) with respect to services described in section 1395x(s)(2)(K) of this title (relating to services furnished by physician assistants, nurse practitioners, or clinic nurse specialists), the amounts paid shall be equal to 80 percent of (i) the lesser of the actual charge or 85 percent of the fee schedule amount provided under section 1395w–4 of this title, or (ii) in the case of services as an assistant at surgery, the lesser of the actual charge or 85 percent of the amount that would otherwise be recognized if performed by a physician who is serving as an assistant at surgery, (P) with respect to surgical dressings, the amounts paid shall be the amounts determined under section 1395m(i) of this title, (Q) with respect to items or services for which fee schedules are established pursuant to section 1395u(s) of this title, the amounts paid shall be 80 percent of the lesser of the actual charge or the fee schedule established in such section, (R) with respect to ambulance services, (i) the amounts paid shall be 80 percent of the lesser of the actual charge for the services or the amount determined by a fee schedule established by the Secretary under section 1395m(l) of this title and (ii) with respect to ambulance services described in section 1395m(l)(8) of this title, the amounts paid shall be the amounts determined under section 1395m(g) of this title for outpatient critical access hospital services, (S)(i) except as provided in clause (ii), subject to subparagraph (EE), with respect to drugs and biologicals (including intravenous immune globulin (as defined in section 1395x(zz) of this title)) not paid on a cost or prospective payment basis as otherwise provided in this part (other than items and services described in subparagraph (B)), the amounts paid shall be 80 percent of the lesser of the actual charge or the payment amount established in section 1395u(o) of this title (or, if applicable, under section 1395w–3, 1395w–3a, or 1395w–3b of this title), and (ii) with respect to insulin furnished on or after July 1, 2023, through an item of durable medical equipment covered under section 1395x(n) of this title, the amounts paid shall be, subject to the fourth sentence of this subsection, 80 percent of the payment amount established under section 1395w–3a of this title (or section 1395w–3b of this title, if applicable) for such insulin, (T) with respect to medical nutrition therapy services (as defined in section 1395x(vv) of this title), the amount paid shall be 80 percent (or 100 percent if such services are recommended with a grade of A or B by the United States Preventive Services Task Force for any indication or population and are appropriate for the individual) of the lesser of the actual charge for the services or 85 percent of the amount determined under the fee schedule established under section 1395w–4(b) of this title for the same services if furnished by a physician, (U) with respect to facility fees described in section 1395m(m)(2)(B) of this title, the amounts paid shall be 80 percent of the lesser of the actual charge or the amounts specified in such section, (V) notwithstanding subparagraphs (I) (relating to durable medical equipment), (M) (relating to prosthetic devices and orthotics and prosthetics), and (Q) (relating to 1395u(s) items), with respect to competitively priced items and services (described in section 1395w–3(a)(2) of this title) that are furnished in a competitive area, the amounts paid shall be the amounts described in section 1395w–3(b)(5) of this title, (W) with respect to additional preventive services (as defined in section 1395x(ddd)(1) of this title), the amount paid shall be (i) in the case of such services which are clinical diagnostic laboratory tests, the amount determined under subparagraph (D) (if such subparagraph were applied, by substituting \"100 percent\" for \"80 percent\"), and (ii) in the case of all other such services, 100 percent of the lesser of the actual charge for the service or the amount determined under a fee schedule established by the Secretary for purposes of this subparagraph, (X) with respect to personalized prevention plan services (as defined in section 1395x(hhh)(1) of this title), the amount paid shall be 100 percent of the lesser of the actual charge for the services or the amount determined under the payment basis determined under section 1395w–4 of this title, (Y) subject to subsection (dd), with respect to preventive services described in subparagraphs (A) and (B) of section 1395x(ddd)(3) of this title that are appropriate for the individual and, in the case of such services described in subparagraph (A), are recommended with a grade of A or B by the United States Preventive Services Task Force for any indication or population, the amount paid shall be 100 percent of (i) except as provided in clause (ii), the lesser of the actual charge for the services or the amount determined under the fee schedule that applies to such services under this part, and (ii) in the case of such services that are covered OPD services (as defined in subsection (t)(1)(B)), the amount determined under subsection (t), (Z) with respect to Federally qualified health center services for which payment is made under section 1395m(o) of this title, the amounts paid shall be 80 percent of the lesser of the actual charge or the amount determined under such section, (AA) with respect to an applicable disposable device (as defined in paragraph (2) of section 1395m(s) of this title) furnished to an individual pursuant to paragraph (1) of such section, the amount paid shall be equal to 80 percent of the lesser of the actual charge or the amount determined under paragraph (3) of such section, (BB) with respect to home infusion therapy, the amount paid shall be an amount equal to 80 percent of the lesser of the actual charge for the services or the amount determined under section 1395m(u) of this title, (CC) with respect to opioid use disorder treatment services furnished during an episode of care, the amount paid shall be equal to the amount payable under section 1395m(w) of this title less any copayment required as specified by the Secretary, (DD) with respect to a specified COVID–19 testing-related service described in paragraph (1) of subsection (cc) for which payment may be made under a specified outpatient payment provision described in paragraph (2) of such subsection, the amounts paid shall be 100 percent of the payment amount otherwise recognized under such respective specified outpatient payment provision for such service, (EE) with respect to a part B rebatable drug (as defined in paragraph (2) of section 1395w–3a(i) of this title) furnished on or after April 1, 2023, for which the payment amount for a calendar quarter under paragraph (3)(A)(ii)(I) of such section (or, in the case of a part B rebatable drug that is a selected drug (as defined in section 1320f–1(c) of this title for which, the payment amount described in section 1395w–3a(b)(1)(B) of this title) for such drug for such quarter exceeds the inflation-adjusted payment under paragraph (3)(A)(ii)(II) of such section for such quarter, the amounts paid shall be equal to the percent of the payment amount under paragraph (3)(A)(ii)(I) of such section or section 1395w–3a(b)(1)(B) of this title, as applicable, that equals the difference between (i) 100 percent, and (ii) the percent applied under section 1395w–3a(i)(5)(B) of this title 3 (FF) with respect to marriage and family therapist services and mental health counselor services under section 1395x(s)(2)(II) of this title, the amounts paid shall be 80 percent of the lesser of the actual charge for the services or 75 percent of the amount determined for payment of a psychologist under subparagraph (L), (GG) with respect to lymphedema compression treatment items (as defined in section 1395x(mmm) of this title), the amount paid shall be equal to 80 percent of the lesser of the actual charge or the amount determined under the payment basis determined under section 1395m(z) of this title, and (HH) with respect to items and services related to the administration of intravenous immune globulin furnished on or after January 1, 2024, as described in section 1395x(zz) of this title, the amounts paid shall be the lesser of the 80 percent of the actual charge or the payment amount established under section 1395u(o)(8) of this title;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1395l?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1395l. Payment of benefits","tname":"The Public Health and Welfare","by":{"0":"passim, 17, 26, 26, 17, 27, passim, passim, 21, 21, 22, 25, 26, 8, 20, 25, 8, 20, 25, 25, passim, 4, 20, 21, 22, 23, 4, 23, 24, passim, passim, passim, 17, 25, 26, 17, 26, passim, 5, 33, 6, passim, passim, passim, 6, 39, passim, 7, 32, 33, 7, 33, 7, 33, 36, 7, 32, 33, 34, 36, 7, 32, 33, 7, 32, passim, 7, 22, 23, 24, 17, 26, 25, 17, 25, 27, 17, 27, 17, 27, 27","1":"4, 4, 24, 44, 24, 31, 32, 34, 35, 35, 46, 28, 35, 29, 4, 4, 5, 35, 4, 4, 24, 35, 12, 25, 30, passim, 4, 18, 23, 24, 27, 28, 4, 18, 24, 25, 28, 5, 31, 5, 31, 6, 27, 33, passim, passim, 5, 24, 43, 28, 32, 5, 5, 28, 6, 24, 33, 40, 12, 25, 29, 23","2":"3, 3, 18, 4, 10, 23, 23, 21, 6, 4, 7, 4, 23, 6, 21, 1, 16, passim, 4, 14, 17, 4, 17, 22, 21, 9, 10, 11, 14, 16, 16, 17, 5"}},{"t":"usc","label":"42 U.S.C. § 1395w-3a","url":"https://www.law.cornell.edu/uscode/text/42/1395w-3a","subs":["(c)","(c)(3)","(b)(1)(A)","(c)(2)(A)"],"stext":{"head":"§1395w–3a. Use of average sales price payment methodology","paras":[[0,"(a) Application"],[0,"(1) In general"],[1,"Except as provided in paragraph (2), this section shall apply to payment for drugs and biologicals that are described in section 1395u(o)(1)(C) of this title and that are furnished on or after January 1, 2005."],[0,"(2) Election"],[1,"This section shall not apply in the case of a physician who elects under subsection (a)(1)(A)(ii) of section 1395w–3b of this title for that section to apply instead of this section for the payment for drugs and biologicals."],[0,"(b) Payment amount"],[0,"(1) In general"],[1,"Subject to paragraph (7) and subsections (d)(3)(C) and (e), the amount of payment determined under this section for the billing and payment code for a drug or biological (based on a minimum dosage unit) is, subject to applicable deductible and coinsurance—"],[2,"(A) in the case of a multiple source drug (as defined in subsection (c)(6)(C)), 106 percent of the amount determined under paragraph (3) for a multiple source drug furnished before April 1, 2008, or 106 percent of the amount determined under paragraph (6) for a multiple source drug furnished on or after April 1, 2008;"],[2,"(B) in the case of a single source drug or biological (as defined in subsection (c)(6)(D)), 106 percent of the amount determined under paragraph (4) or in the case of such a drug or biological product that is a selected drug (as referred to in section 1320f–1(c) of this title), with respect to a price applicability period (as defined in section 1320f(b)(2) of this title), 106 percent of the maximum fair price (as defined in section 1320f(c)(3) of this title) applicable for such drug and a year during such period; or"],[2,"(C) in the case of a biosimilar biological product (as defined in subsection (c)(6)(H)), the amount determined under paragraph (8)."],[0,"(2) Specification of unit"],[0,"(A) Specification by manufacturer"],[2,"The manufacturer of a drug or biological shall specify the unit associated with each National Drug Code (including package size) as part of the submission of data under section 1396r–8(b)(3)(A)(iii) of this title or subsection (f)(2), as applicable."],[0,"(B) Unit defined"],[2,"In this section, the term \"unit\" means, with respect to each National Drug Code (including package size) associated with a drug or biological, the lowest identifiable quantity (such as a capsule or tablet, milligram of molecules, or grams) of the drug or biological that is dispensed, exclusive of any diluent without reference to volume measures pertaining to liquids. For years after 2004, the Secretary may establish the unit for a manufacturer to report and methods for counting units as the Secretary determines appropriate to implement this section."],[0,"(3) Multiple source drug"],[1,"For all drug products included within the same multiple source drug billing and payment code, the amount specified in this paragraph is the volume-weighted average of the average sales prices reported under section 1396r–8(b)(3)(A)(iii) of this title or subsection (f)(2), as applicable, determined by—"],[2,"(A) computing the sum of the products (for each National Drug Code assigned to such drug products) of—"],[3,"(i) the manufacturer's average sales price (as defined in subsection (c)); and"],[3,"(ii) the total number of units specified under paragraph (2) sold; and"],[2,"(B) dividing the sum determined under subparagraph (A) by the sum of the total number of units under subparagraph (A)(ii) for all National Drug Codes assigned to such drug products."],[0,"(4) Single source drug or biological"],[1,"The amount specified in this paragraph for a single source drug or biological is the lesser of the following:"],[0,"(A) Average sales price"],[2,"The average sales price as determined using the methodology applied under paragraph (3) for single source drugs and biologicals furnished before April 1, 2008, and using the methodology applied under paragraph (6) for single source drugs and biologicals furnished on or after April 1, 2008, for all National Drug Codes assigned to such drug or biological product."],[0,"(B) Wholesale acquisition cost (WAC)"],[2,"The wholesale acquisition cost (as defined in subsection (c)(6)(B)) using the methodology applied under paragraph (3) for single source drugs and biologicals furnished before April 1, 2008, and using the methodology applied under paragraph (6) for single source drugs and biologicals furnished on or after April 1, 2008, for all National Drug Codes assigned to such drug or biological product."],[0,"(5) Basis for payment amount"],[1,"The payment amount shall be determined under this subsection based on information reported under subsection (f) and without regard to any special packaging, labeling, or identifiers on the dosage form or product or package."],[0,"(6) Use of volume-weighted average sales prices in calculation of average sales price"],[0,"(A) In general"],[2,"For all drug products included within the same multiple source drug billing and payment code, the amount specified in this paragraph is the volume-weighted average of the average sales prices reported under section 1396r–8(b)(3)(A)(iii) of this title or subsection (f)(2), as applicable, determined by—"],[3,"(i) computing the sum of the products (for each National Drug Code assigned to such drug products) of—"],[4,"(I) the manufacturer's average sales price (as defined in subsection (c)), determined by the Secretary without dividing such price by the total number of billing units for the National Drug Code for the billing and payment code; and"],[4,"(II) the total number of units specified under paragraph (2) sold; and"],[3,"(ii) dividing the sum determined under clause (i) by the sum of the products (for each National Drug Code assigned to such drug products) of—"],[4,"(I) the total number of units specified under paragraph (2) sold; and"],[4,"(II) the total number of billing units for the National Drug Code for the billing and payment code."],[0,"(B) Billing unit defined"],[2,"For purposes of this subsection, the term \"billing unit\" means the identifiable quantity associated with a billing and payment code, as established by the Secretary."],[0,"(7) Special rule"],[1,"Beginning with April 1, 2008, the payment amount for—"],[2,"(A) each single source drug or biological described in section 1395u(o)(1)(G) of this title that is treated as a multiple source drug because of the application of subsection (c)(6)(C)(ii) is the lower of—"],[3,"(i) the payment amount that would be determined for such drug or biological applying such subsection; or"],[3,"(ii) the payment amount that would have been determined for such drug or biological if such subsection were not applied; and"],[2,"(B) a multiple source drug described in section 1395u(o)(1)(G) of this title (excluding a drug or biological that is treated as a multiple source drug because of the application of such subsection) is the lower of—"],[3,"(i) the payment amount that would be determined for such drug or biological taking into account the application of such subsection; or"],[3,"(ii) the payment amount that would have been determined for such drug or biological if such subsection were not applied."],[0,"(8) Biosimilar biological product"],[0,"(A) In general"],[2,"Subject to subparagraph (B), the amount specified in this paragraph for a biosimilar biological product described in paragraph (1)(C) is the sum of—"],[3,"(i) the average sales price as determined using the methodology described under paragraph (6) applied to a biosimilar biological product for all National Drug Codes assigned to such product in the same manner as such paragraph is applied to drugs described in such paragraph; and"],[3,"(ii) 6 percent of the amount determined under paragraph (4) for the reference biological product (as defined in subsection (c)(6)(I))."],[0,"(B) Temporary payment increase"],[0,"(i) In general"],[3,"In the case of a qualifying biosimilar biological product that is furnished during the applicable 5-year period for such product, the amount specified in this paragraph for such product with respect to such period is the sum determined under subparagraph (A), except that clause (ii) of such subparagraph shall be applied by substituting \"8 percent\" for \"6 percent\"."],[0,"(ii) Applicable 5-year period"],[3,"For purposes of clause (i), the applicable 5-year period for a qualifying biosimilar biological product is—"],[4,"(I) in the case of such a product for which payment was made under this paragraph as of September 30, 2022, the 5-year period beginning on October 1, 2022; and"],[4,"(II) in the case of such a product for which payment is first made under this paragraph during a calendar quarter during the period beginning October 1, 2022, and ending December 31, 2027, the 5-year period beginning on the first day of such calendar quarter during which such payment is first made."],[0,"(iii) Qualifying biosimilar biological product defined"],[3,"For purposes of this subparagraph, the term \"qualifying biosimilar biological product\" means a biosimilar biological product described in paragraph (1)(C) with respect to which—"],[4,"(I) in the case of a product described in clause (ii)(I), the average sales price under paragraph (8)(A)(i) for a calendar quarter during the 5-year period described in such clause is not more than the average sales price under paragraph (4)(A) for such quarter for the reference biological product; and"],[4,"(II) in the case of a product described in clause (ii)(II), the average sales price under paragraph (8)(A)(i) for a calendar quarter during the 5-year period described in such clause is not more than the average sales price under paragraph (4)(A) for such quarter for the reference biological product."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1395w-3a?type=usc&year=mostrecent&link-type=html"},"head":"§1395w–3a. Use of average sales price payment methodology","tname":"The Public Health and Welfare","by":{"0":"6, 32, 44","1":"32, 32, 8, 32, 8"}},{"t":"law","label":"Pub. L. No. 108-173","url":"https://www.govinfo.gov/link/plaw/108/public/173","by":{"0":"1, 5","1":"4"}},{"t":"law","label":"Pub. L. No. 102-585","url":"https://www.govinfo.gov/link/statute/106/4943","by":{"0":"9"}},{"t":"law","label":"Pub. L. No. 105-33","url":"https://www.govinfo.gov/link/plaw/105/public/33","by":{"0":"24","1":"3"}},{"t":"law","label":"Pub. L. No. 106-113","url":"https://www.govinfo.gov/link/plaw/106/public/113","by":{"0":"25, 25, 25"}},{"t":"law","label":"Pub. L. No. 106-554","url":"https://www.govinfo.gov/link/plaw/106/public/554","by":{"0":"44"}},{"t":"law","label":"Pub. L. No. 111-148","url":"https://www.govinfo.gov/link/plaw/111/public/148","by":{"0":"26, 9, 40"}},{"t":"law","label":"Pub. L. No. 114-74","url":"https://www.govinfo.gov/link/plaw/114/public/74","by":{"0":"25"}},{"t":"reg","label":"FEDERAL REGULATIONS, 77 Fed. Reg. 68,210","url":"https://www.govinfo.gov/link/fr/77/68210","by":{"0":"passim","1":"8, 13","2":"3, 19"}},{"t":"reg","label":"80 Fed. Reg. 70,298","url":"https://www.govinfo.gov/link/fr/80/70298","by":{"0":"8, 42, 44"}},{"t":"reg","label":"82 Fed. Reg. 52,356","url":"https://www.govinfo.gov/link/fr/82/52356","by":{"0":"passim","1":"passim","2":"19"}},{"t":"reg","label":"83 Fed. Reg. 58,818","url":"https://www.govinfo.gov/link/fr/83/58818","by":{"0":"11, 27","1":"13"}},{"t":"reg","label":"84 Fed. Reg. 39,398","url":"https://www.govinfo.gov/link/fr/84/39398","by":{"0":"29"}},{"t":"reg","label":"85 Fed. Reg. 85,866","url":"https://www.govinfo.gov/link/fr/85/85866","by":{"0":"34","1":"13, 42","2":"15"}},{"t":"case","label":"American Hosp. Ass’n v. Azar","cite":"964 F.3d 1230","y":2020,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/964/1230/","by":{"1":"20, 21, 28, 29, 30"}},{"t":"case","label":"Azar v. Allina Health Servs.","cite":"139 S. Ct. 1804","y":2019,"id":"2018/17-1484","sc":1,"sum":"Because the Department of Health and Human Services neglected its statutory notice-and-comment obligations when it revealed a new policy that dramatically—and retroactively—reduced Medicare payments to hospitals serving low-income patients, its policy must be vacated.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"2, 4, 22, 48"}},{"t":"case","label":"Block v. Community Nutrition Inst.","cite":"467 U.S. 340","y":1984,"id":"1983/83-458","sc":1,"sum":"The individual consumers may not obtain judicial review of the milk market orders in question.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23, 24, 25, 26"}},{"t":"case","label":"Bowen v. Georgetown Univ. Hosp.","cite":"488 U.S. 204","y":1988,"id":"1988/87-1097","sc":1,"sum":"Under the Medicare program, the Government reimburses health care providers for expenses incurred in providing medical services to Medicare beneficiaries. The Medicare Act in 42 U. S. C. § 1395x(v)(1)(A) authorizes the Secretary of Health and Human Services (Secretary) to promulgate cost-reimbursement regulations and also provides that \"[s]uch regulations shall... (ii) provide for the making of suitable retroactive …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"3"}},{"t":"case","label":"Cuozzo Speed Techs., LLC v. Lee","cite":"136 S. Ct. 2131","y":2016,"id":"2015/15-446","sc":1,"sum":"The Court held that the Patent Trial and Appeal Board may apply the broadest reasonable interpretation of patent claims during an inter partes review proceeding, and such a proceeding is not judicially reviewable.","sumSrc":"Oyez","by":{"1":"25, 26, 27, 48","2":"22"}},{"t":"case","label":"FCC v. National Citizens Comm. for Broad.","cite":"436 U.S. 775","y":1978,"id":"1977/76-1471","sc":1,"sum":"The challenged regulations are valid in their entirety.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"48","2":"22"}},{"t":"case","label":"Fresno Cmty. Hosp. & Med. Ctr. v. Cochran","cite":"987 F.3d 158","y":2021,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/987/158/","sum":"Concluding, in a case under the Medicare statute, that an argument that courts may “ ‘disregard statutory bars on judicial review’ when the agency has violated the underlying statute * * * would essentially remove the statutory bar against judicial review”.","sumSrc":"brief:1","by":{"1":"31"}},{"t":"case","label":"Good Samaritan Hosp. v. Shalala","cite":"508 U.S. 402","y":1993,"id":"1992/91-2079","sc":1,"sum":"Title 42 U. S. C. § 1395f(b)(1) requires the Secretary of Health and Human Services to reimburse the lesser of the \"customary charges\" or the \"reasonable cost[s]\" of providers of health care services to Medicare beneficiaries, while § 1395x(v)(1)(A) empowers the Secretary to issue regulations setting forth the methods to be used in computing reasonable costs, which may include the establishment of appropriate cost …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"3"}},{"t":"case","label":"Nielsen v. Preap","cite":"139 S. Ct. 954","y":2019,"id":"2018/16-1363","sc":1,"sum":"The Ninth Circuit’s judgments—that respondents, who are deportable for certain specified crimes, are not subject to 8 U. S. C. §1226(c)(2)’s mandatory-detention requirement because they were not arrested by immigration officials as soon as they were released from jail—are reversed, and the cases are remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"41"}},{"t":"case","label":"Painter v. Shalala","cite":"97 F.3d 1351","y":1996,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/97/1351/","by":{"1":"23"}},{"t":"case","label":"Regions Hosp. v. Shalala","cite":"522 U.S. 448","y":1998,"id":"1997/96-1375","sc":1,"ar":1,"sum":"The Court held that the reaudit rule is a reasonable interpretation of the GME Amendment and that it is not impermissibly retroactive.","sumSrc":"Oyez","by":{"1":"35, 48"}},{"t":"case","label":"Sebelius v. Auburn Reg’l Med. Ctr.","cite":"568 U.S. 145","y":2013,"id":"2012/11-1231","sc":1,"sum":"The Court held that the statute of limitations for filing a claim with the Provider Reimbursement Review Board may be extended up to 3 years.","sumSrc":"Oyez","by":{"1":"48, 49","2":"22"}},{"t":"case","label":"Shalala v. Illinois Council on Long Term Care, Inc.","cite":"529 U.S. 1","y":2000,"id":"1999/98-1109","sc":1,"sum":"The Court held that the Medicare Act barred federal-question jurisdiction of the Council's challenges to the validity of various Medicare regulations. The Court concluded that the Council must proceed instead through the special review channel that the Medicare statutes create.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Thryv, Inc. v. Click-To-Call Techs., LP","cite":"140 S. Ct. 1367","y":2020,"id":"2019/18-916","sc":1,"sum":"The Court held that 35 U.S.C. §314(d) precludes judicial review of a Patent Trial and Appeal Board’s decision to institute inter partes review upon finding that §315(b)’s time bar did not apply.","sumSrc":"Oyez","by":{"1":"23, 24, 25, 26"}},{"t":"case","label":"United States v. Briggs","cite":"141 S. Ct. 467","y":2020,"id":"2020/19-108","sc":1,"sum":"Respondents’ prosecutions for military rape were timely commenced under the Uniform Code of Military Justice’s statute of limitations.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"46"}},{"t":"case","label":"United States v. Erika, Inc.","cite":"456 U.S. 201","y":1982,"id":"1981/80-1594","sc":1,"sum":"The Court of Claims has no jurisdiction to review determinations by private insurance carriers of the amount of benefits payable under Part B of the Medicare program.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"United States v. Mead Corp.","cite":"533 U.S. 218","y":2001,"id":"2000/99-1434","sc":1,"sum":"The Court held that the \"administrative implementation of a particular statutory provision qualifies for [the greatest level of deference accorded under Chevron U.S.A. Inc. v. Natural Resources Defense Council] when it appears that Congress delegated authority to the agency generally to make rules carrying the force of law, and that the agency interpretation claiming deference was promulgated in the exercise of that authority.\" Justice Souter wrote that \"a tariff classification has no claim to judicial deference under Chevron, there being no indication that Congress intended such a ruling to carry the force of law, but we hold that under Skidmore v. Swift & Co., the ruling is eligible to claim respect according to its persuasiveness.\".","sumSrc":"Oyez","by":{"1":"48"}},{"t":"law","label":"Pub. L. No. 112-240","url":"https://www.govinfo.gov/link/plaw/112/public/240","by":{"1":"23"}},{"t":"usc","label":"42 U.S.C. § 1395c","url":"https://www.law.cornell.edu/uscode/text/42/1395c","by":{"1":"2"}},{"t":"usc","label":"42 U.S.C. § 1395ff","url":"https://www.law.cornell.edu/uscode/text/42/1395ff","subs":["(b)"],"by":{"1":"20"}},{"t":"usc","label":"42 U.S.C. § 1395hh","url":"https://www.law.cornell.edu/uscode/text/42/1395hh","subs":["(a)(2)"],"by":{"1":"22"}},{"t":"usc","label":"42 U.S.C. § 1395ii","url":"https://www.law.cornell.edu/uscode/text/42/1395ii","by":{"1":"13"}},{"t":"usc","label":"42 U.S.C. § 1395j","url":"https://www.law.cornell.edu/uscode/text/42/1395j","by":{"1":"3"}},{"t":"usc","label":"42 U.S.C. § 1395u","url":"https://www.law.cornell.edu/uscode/text/42/1395u","subs":["(o)"],"by":{"1":"6"}},{"t":"usc","label":"42 U.S.C. § 1395w-3b","url":"https://www.law.cornell.edu/uscode/text/42/1395w-3b","by":{"1":"6"}},{"t":"usc","label":"42 U.S.C. § 405","url":"https://www.law.cornell.edu/uscode/text/42/405","subs":["(g)","(h)"],"by":{"1":"13, 13"}},{"t":"usc","label":"42 U.S.C. § 1396r-8","url":"https://www.law.cornell.edu/uscode/text/42/1396r-8","subs":["(c)(1)(C)(i)"],"by":{"1":"8"}},{"t":"reg","label":"42 C.F.R. § 405.926","url":"https://www.ecfr.gov/current/title-42/section-405.926","subs":["(c)"],"by":{"1":"22, 27"}},{"t":"reg","label":"70 Fed. Reg. 68,516","url":"https://www.govinfo.gov/link/fr/70/68516","by":{"1":"7"}},{"t":"reg","label":"73 Fed. Reg. 69,726","url":"https://www.govinfo.gov/link/fr/73/69726","by":{"1":"6"}},{"t":"reg","label":"84 Fed. Reg. 61,142,","url":"https://www.govinfo.gov/link/fr/84/61142","by":{"1":"13"}},{"t":"reg","label":"86 Fed. Reg. 42,018","url":"https://www.govinfo.gov/link/fr/86/42018","by":{"1":"13"}},{"t":"case","label":"Batterton v. Francis","cite":"432 U.S. 416","y":1977,"id":"1976/75-1181","sc":1,"sum":"The regulation is a proper exercise of the Secretary's statutory authority and is reasonable.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"22"}},{"t":"case","label":"Schweiker v. Gray Panthers","cite":"453 U.S. 34","y":1981,"id":"1980/80-756","sc":1,"sum":"The regulations at issue are consistent with the statutory scheme and are reasonable exercises of the authority delegated to the Secretary. Pp. 43-50. …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"22"}},{"t":"reg","label":"FEDERAL REGULATIONS, 71 Fed. Reg. 67,960","url":"https://www.govinfo.gov/link/fr/71/67960","by":{"2":"9"}},{"t":"reg","label":"86 Fed. Reg. 63,458","url":"https://www.govinfo.gov/link/fr/86/63458","by":{"2":"7"}}]};